export const MELCOR_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/melcor-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getMelcorStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(MELCOR_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
